//! Native Document copies preserve metadata and independently owned topology.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><div id=mount></div></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://document-clone.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}
#[test]
fn document_clone_xml_new_implementation_owners_names_units_and_independent_mutations(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var dtype=document.implementation.createDocumentType('Root','\ud800','\udfff'),d=document.implementation.createDocument('urn:original','p:Root',dtype),root=d.documentElement,part=d.createCDATASection('\ud800A\udfff'),comment=d.createComment('marker'),pi=d.createProcessingInstruction('original','data'),watch=new MutationObserver(function(){});root.appendChild(part);root.appendChild(comment);root.appendChild(pi);watch.observe(d,{subtree:true,childList:true,characterData:true});
var c=d.cloneNode(true),r=c.documentElement,list=c.childNodes;
if(c===d||!(c instanceof XMLDocument)||Object.getPrototypeOf(c)!==XMLDocument.prototype||c.nodeType!==9||c.ownerDocument!==null||c.parentNode!==null||c.defaultView!==null||c.contentType!=='application/xml'||c.URL!==d.URL||c.baseURI!==d.baseURI||c.characterSet!=='UTF-8'||c.compatMode!==d.compatMode||c.implementation===d.implementation||c.implementation!==c.implementation||list.length!==2||c.firstChild!==c.doctype||list[1]!==r)throw 'real cloned document records';
if(r===root||r.ownerDocument!==c||r.parentNode!==c||r.namespaceURI!=='urn:original'||r.prefix!=='p'||r.localName!=='Root'||r.nodeName!=='p:Root'||c.doctype===dtype||c.doctype.ownerDocument!==c||c.doctype.publicId.charCodeAt(0)!==0xd800||c.doctype.systemId.charCodeAt(0)!==0xdfff)throw 'cloned owners expanded names and doctype';
if(r.firstChild===part||r.firstChild.ownerDocument!==c||!(r.firstChild instanceof CDATASection)||r.firstChild.nodeType!==4||r.firstChild.data!==part.data||r.childNodes[1]===comment||r.childNodes[2]===pi||r.childNodes[2].target!=='original')throw 'cloned character records';
r.firstChild.data='changed';r.removeChild(r.childNodes[1]);c.removeChild(c.doctype);if(part.data!=='\ud800A\udfff'||root.childNodes.length!==3||d.doctype!==dtype||dtype.ownerDocument!==d||watch.takeRecords().length||c.doctype!==null||list.length!==1)throw 'independent cloned state';
var made=c.implementation.createDocumentType('Second','',''),next=c.implementation.createDocument(null,'Next',made);if(made.ownerDocument!==next||next.doctype!==made||next===c||next.documentElement.ownerDocument!==next)throw 'new associated implementation';
var shallow=d.cloneNode();if(!(shallow instanceof XMLDocument)||shallow.documentElement!==null||shallow.doctype!==null||shallow.childNodes.length||shallow.contentType!==d.contentType||shallow.implementation===d.implementation||shallow.baseURI!==d.baseURI)throw 'genuine shallow XML document';
var raw=document.implementation.createDocument('\ud800','q:Case'),rawCopy=raw.cloneNode(true);if(rawCopy.documentElement===raw.documentElement||rawCopy.documentElement.namespaceURI.charCodeAt(0)!==0xd800||rawCopy.documentElement.prefix!=='q'||rawCopy.documentElement.localName!=='Case'||rawCopy.documentElement.ownerDocument!==rawCopy||rawCopy.baseURI!==raw.baseURI)throw 'real cloned raw namespace record';
"#);assert!(!page.has_navigation_request());assert!(page.take_dynamic_scripts().is_empty()&&page.take_dynamic_stylesheets().is_empty());
}
#[test]
fn document_clone_html_parser_modes_title_base_override_and_current_base_element_are_real(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var d=document.implementation.createHTMLDocument('original'),base=d.createElement('base');base.setAttribute('href','https://base-clone.test/original/');d.head.appendChild(base);var item=d.createElement('span');item.textContent='actual data';d.body.appendChild(item);var c=d.cloneNode(true),shallow=d.cloneNode(false);
if(c===d||Object.getPrototypeOf(c)!==Document.prototype||c instanceof XMLDocument||c.documentElement.ownerDocument!==c||c.head.ownerDocument!==c||c.body.ownerDocument!==c||c.title!=='original'||c.body.firstChild===item||c.body.firstChild.textContent!=='actual data'||c.contentType!=='text/html'||c.compatMode!=='CSS1Compat'||shallow.documentElement!==null||shallow.title!==''||shallow.baseURI!=='https://base-clone.test/original/')throw 'real HTML copy metadata';
base.setAttribute('href','https://base-clone.test/source-changed/');if(shallow.baseURI!=='https://base-clone.test/original/'||c.baseURI!=='https://base-clone.test/original/'||d.baseURI!=='https://base-clone.test/source-changed/')throw 'retained source base snapshot';
var copiedBase=c.head.childNodes[1];if(copiedBase.localName!=='base')throw 'actual copied base';copiedBase.setAttribute('href','https://base-clone.test/copy-changed/');if(c.baseURI!=='https://base-clone.test/copy-changed/'||d.baseURI!=='https://base-clone.test/source-changed/')throw 'current base element precedes override';c.head.removeChild(copiedBase);if(c.baseURI!=='https://base-clone.test/original/')throw 'native base override after removal';
var parsed=new DOMParser().parseFromString('<html><body><p>quirks</p></body></html>','text/html'),copy=parsed.cloneNode(true);if(copy.compatMode!=='BackCompat'||copy.URL!==parsed.URL||copy.baseURI!==parsed.baseURI||copy.documentElement.ownerDocument!==copy||copy.body.firstChild.textContent!=='quirks')throw 'parsed HTML kind mode and URL';
"#);
}
#[test]
fn document_clone_retained_refusal_has_no_source_or_identity_prefix_and_recovers(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var original=document.implementation.createDocument('urn:original','p:Root');original.documentElement.appendChild(original.createCDATASection('data'));var saved=original.documentElement,watch=new MutationObserver(function(){});watch.observe(original,{subtree:true,childList:true,characterData:true});");
 let before=(doc.nodes.len(),page.state.retained,page.state.dom_commits);let limit=page.state.retained_limit;page.state.retained_limit=page.state.retained;
 assert_eq!(page.console_eval(&mut doc,&mut forms,"original.cloneNode(true);").errors,1);assert_eq!((doc.nodes.len(),page.state.retained,page.state.dom_commits),before);page.state.retained_limit=limit;
 run(&mut doc,&mut forms,&mut page,"if(original.documentElement!==saved||saved.ownerDocument!==original||saved.firstChild.data!=='data'||watch.takeRecords().length)throw 'no source prefix';var recovered=original.cloneNode(true);if(recovered===original||recovered.documentElement===saved||recovered.documentElement.ownerDocument!==recovered||recovered.documentElement.firstChild.nodeType!==4||recovered.documentElement.textContent!=='data')throw 'fresh clone recovery';");
}
#[test]
fn document_clone_template_owner_boundary_and_resource_inertness_remain_explicit(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var source=document.implementation.createHTMLDocument('template source'),template=source.createElement('template');source.body.appendChild(template);var saved=template.content,caught=false;try{source.cloneNode(true);}catch(e){caught=e.name==='NotSupportedError'&&e instanceof DOMException&&e.message.indexOf('template-owner')>=0;}if(!caught||source.body.firstChild!==template||template.content!==saved||saved.ownerDocument===source)throw 'unimplemented template owner does not fabricate clone';var shallow=source.cloneNode(false);if(shallow.documentElement!==null||shallow.title!==''||shallow===source)throw 'shallow clone does not copy template contents';
var inert=new DOMParser().parseFromString('<!doctype html><html><head><script>window.cloneEscaped=true;</script></head><body><img src="https://no-clone-resource.test/image.png"><p>data</p></body></html>','text/html'),copy=inert.cloneNode(true);if(copy.defaultView!==null||copy.documentElement.ownerDocument!==copy||typeof window.cloneEscaped!=='undefined'||copy.body.lastChild.textContent!=='data')throw 'document clone remains resource inert';
"#);assert!(!page.has_navigation_request());assert!(page.take_dynamic_scripts().is_empty()&&page.take_dynamic_stylesheets().is_empty());let(a,b,c)=page.take_image_changes();assert!(a.is_empty()&&b.is_empty()&&c.is_empty());
}
